const int MOD = 998244353;

string f(long long x, long long y) {
    string sx = to_string(x);
    string sy = to_string(y);
    int p = sx.length();
    int q = sy.length();
    string result = "";
    int i = p - 1;
    int j = q - 1;
    while (i >= 0 || j >= 0) {
        if (i >= 0) {
            result += sx[i];
            i--;
        }
        if (j >= 0) {
            result += sy[j];
            j--;
        }
    }
    reverse(result.begin(), result.end());
    return result;
}

