        }

        bool possible = false;
        for (int k = 1; k <= n; ++k) {
            vector<int> b = a;
            bool increasing = true;
            for (int i = 0; i < k - 1; ++i) {
                if (b[i] >= b[i + 1]) {
                    increasing = false;
                    break;
                }
            }

            if (!increasing) {
                for (int i = 0; i < k - 1; ++i) {
                    if (b[i] >= b[i + 1]) {
                        int diff = b[i] - b[i + 1] + 1;
                        if (b[i] >= diff) {
                            b[i] -= diff;
                        } else {
                            increasing = false;
                            break;
                        }
                    }
                }
            }

            if (increasing) {
                bool decreasing = true;
                for (int i = k; i < n - 1; ++i) {
                    if (b[i] <= b[i + 1]) {
                        decreasing = false;
                        break;
                    }
                }

                if (!decreasing) {
                    for (int i = k; i < n - 1; ++i) {
                        if (b[i] <= b[i + 1]) {
                            int diff = b[i + 1] - b[i] + 1;
                            if (b[i + 1] >= diff) {
                                b[i + 1] -= diff;
                            } else {
                                decreasing = false;
                                break;
                            }
                        }
                    }
                }

                if (decreasing) {
                    possible = true;
                    break;
