              count = (count + 1) % MOD;
            } else if (current_factors.size() == 1 && current_factors[0].first == 3){
                count = (count + 1) % MOD;
            }
            continue;
        }





        bool valid = true;

        for(int k = 0; k < current_factors.size(); ++k) {
            bool isPrime = true;
            if(current_factors[k].first <= 1) {
