long long gcd(long long a, long long b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

long long lcm(long long a, long long b) {
    return (a * b) / gcd(a, b);
}

int main() {
    long long x;
    cin >> x;

    if (x == 1) {
        cout << 1 << " " << 1 << endl;
        return 0;
    }

