    long long a_best = -1;
    long long b_best = -1;

    for (long long a = 1; a * a <= x; ++a) {
        if (x % a == 0) {
            long long b = x / a;
            if (lcm(a, b) == x) {
                long long current_max = max(a, b);
                if (min_max == -1 || current_max < min_max) {
                    min_max = current_max;
                    a_best = a;
                    b_best = b;
                }
            }
        }
    }

    for (long long b = 1; b * b <= x; ++b) {
        if (x % b == 0) {
            long long a = x / b;
