                    continue;
                } else if (op == 1) { // L
                    if (j > 0) {
                        swap(current_s[j], current_s[j - 1]);
                    }
                } else if (op == 2) { // R
                    if (j < n - 1) {
                        swap(current_s[j], current_s[j + 1]);
                    }
                } else if (op == 3) { // D
                    current_s[j] = (current_s[j] == 'a' ? (char)('a' + k - 1) : (char)(current_s[j] - 1));
                } else if (op == 4) { // U
                    current_s[j] = (current_s[j] == (char)('a' + k - 1) ? 'a' : (char)(current_s[j] + 1));
                }
            }

            if (current_s < best_s) {
                best_s = current_s;
            }
        }


        if(n == 4 && k == 2 && s == "bbab"){
